WITH QUAL_REQS_CTE AS
(
    SELECT 
    POSITION_HKEY,
    -- _CURRENT_ACTIVE_TIMESTAMP,
    _AIRBYTE_EXTRACTED_AT AS AIRBYTE_DATE,
    QUALIFIED_DATE AS FACT_DATE,
    NUMBER_OF_OPENINGS AS QUALIFIED_REQS,
    RECORDTYPEID,
    RECORD_TYPE,
    DIVISION,
    DOMAIN,
    SEGMENT
    FROM {{ ref('sat_bh4sf_position_bvv_curr') }}
    WHERE QUALIFIED_DATE IS NOT NULL
)
, CLOSED_REQS_CTE AS
(
    SELECT 
    POSITION_HKEY,
	-- _CURRENT_ACTIVE_TIMESTAMP,
	_AIRBYTE_EXTRACTED_AT AS AIRBYTE_DATE,
    CLOSED_DATE AS FACT_DATE,
    NUMBER_OF_OPENINGS AS CLOSED_REQS,
    RECORDTYPEID,
	RECORD_TYPE,
    DIVISION,
    DOMAIN,
    SEGMENT
    FROM {{ ref('sat_bh4sf_position_bvv_curr') }}
    WHERE CLOSED_DATE IS NOT NULL
    AND QUALIFIED_DATE IS NOT NULL
)
, FACT_DATE_CTE AS
(
    SELECT POSITION_HKEY, AIRBYTE_DATE, FACT_DATE, RECORD_TYPE, DIVISION, DOMAIN, SEGMENT
    FROM QUAL_REQS_CTE
    UNION
    SELECT POSITION_HKEY, AIRBYTE_DATE, FACT_DATE, RECORD_TYPE, DIVISION, DOMAIN, SEGMENT
    FROM CLOSED_REQS_CTE
)
SELECT
    FD.POSITION_HKEY
    , FD.AIRBYTE_DATE
    , FD.FACT_DATE
    , FD.RECORD_TYPE
    , FD.DIVISION
    , FD.DOMAIN
    , FD.SEGMENT
    , QUAL_REQS_CTE.QUALIFIED_REQS
    , CLOSED_REQS_CTE.CLOSED_REQS
FROM FACT_DATE_CTE FD
LEFT JOIN QUAL_REQS_CTE
ON FD.POSITION_HKEY = QUAL_REQS_CTE.POSITION_HKEY AND FD.FACT_DATE = QUAL_REQS_CTE.FACT_DATE
LEFT JOIN CLOSED_REQS_CTE
ON FD.POSITION_HKEY = CLOSED_REQS_CTE.POSITION_HKEY AND FD.FACT_DATE = CLOSED_REQS_CTE.FACT_DATE